using System;using System.Linq;using System.IO;using System.Xml;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
sealed class ProjectInformation {public string Name="",Location="",Office="",OfficeAddress="";public string NameLine{get{return "Project: "+(Name.Length==0?"(not set)":Name);}}public string LocationLine{get{return "Location: "+(Location.Length==0?"(not set)":Location);}}}
static class ProjectInfoStore {
 internal const int MaxTitleLength=2000,MaxLocationLength=500;
 public static string DirectoryPath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BeamTools");
 public static ProjectInformation Read(){string path=Path.Combine(DirectoryPath,"ProjectInformation.xml");if(!File.Exists(path))return new ProjectInformation();var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=32768}))d.Load(r);if(d.DocumentElement.Name!="ProjectInformation")throw new Exception("Invalid saved project information.");return new ProjectInformation{Name=d.DocumentElement.GetAttribute("name"),Location=d.DocumentElement.GetAttribute("location"),Office=d.DocumentElement.GetAttribute("office"),OfficeAddress=d.DocumentElement.GetAttribute("officeAddress")};}
 public static void Save(string name,string location){var current=Read();Save(name,location,current.Office,current.OfficeAddress);}
 public static void Save(string name,string location,string office,string officeAddress){name=(name??"").Replace("\r\n","\n").Replace('\r','\n').Trim();location=(location??"").Replace("\r\n","\n").Replace('\r','\n').Trim();if(name.Length>MaxTitleLength||location.Length>MaxLocationLength)throw new Exception("Project title supports up to "+MaxTitleLength+" characters; location supports up to "+MaxLocationLength+" characters.");office=(office??"").Trim();officeAddress=(officeAddress??"").Trim();if(office.Length>200||officeAddress.Length>200)throw new Exception("Office and address must be at most 200 characters.");var d=new XmlDocument();var root=d.CreateElement("ProjectInformation");root.SetAttribute("office",office);root.SetAttribute("officeAddress",officeAddress);root.SetAttribute("name",name);root.SetAttribute("location",location);d.AppendChild(root);Directory.CreateDirectory(DirectoryPath);string path=Path.Combine(DirectoryPath,"ProjectInformation.xml"),temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{d.Save(temp);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
class ProjectInformationForm:Form {
 public ProjectInformationForm(){AppBrand.Apply(this);if(!AccessCodes.CanUseApp(8))throw new Exception("This app is not included in your current access.");Shown+=(s,e)=>InputFocus.Apply(this);Text="Project Information";ClientSize=new Size(900,560);MinimumSize=new Size(650,480);Font=ModernUi.Body;var scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(24)};var body=new FlowLayoutPanel{Width=940,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Location=new Point(24,24)};body.Controls.Add(new Label{Text="Project information",AutoSize=true,Font=PremiumControls.TitleFont,Margin=new Padding(0,0,0,18)});var fields=new TableLayoutPanel{AutoSize=true,ColumnCount=2,RowCount=2,Margin=Padding.Empty};fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));string[] labels={"Project Title","Project Location","Implementing Office","Office Address"};var inputs=new TextBox[4];for(int i=0;i<4;i++){var field=new FlowLayoutPanel{Width=440,Height=i==0?148:84,FlowDirection=FlowDirection.TopDown,WrapContents=false,Margin=new Padding(0,0,18,8)};field.Controls.Add(new Label{Text=labels[i],AutoSize=true,Margin=new Padding(0,0,0,8)});inputs[i]=new TextBox{Width=418,MaxLength=i==0?ProjectInfoStore.MaxTitleLength:i==1?ProjectInfoStore.MaxLocationLength:200};if(i==0){inputs[i].Multiline=true;inputs[i].AcceptsReturn=true;inputs[i].WordWrap=true;inputs[i].ScrollBars=ScrollBars.Vertical;inputs[i].Height=110;}field.Controls.Add(inputs[i]);fields.Controls.Add(field,i==0?0:(i-1)%2,i==0?0:1+(i-1)/2);if(i==0)fields.SetColumnSpan(field,2);}body.Controls.Add(fields);var note=new Label{Text="Project title: up to 2,000 characters. Paste multiple lines; reports wrap the full title automatically.",AutoSize=true,MaximumSize=new Size(900,0),Margin=new Padding(0,8,0,14),ForeColor=PowTheme.Muted};body.Controls.Add(note);var save=new Button{Text="Save project information",AutoSize=true};body.Controls.Add(save);scroll.Controls.Add(body);Controls.Add(scroll);var current=ProjectInfoStore.Read();inputs[0].Text=current.Name;inputs[1].Text=current.Location;inputs[2].Text=current.Office;inputs[3].Text=current.OfficeAddress;save.Click+=(s,e)=>{try{ProjectInfoStore.Save(inputs[0].Text,inputs[1].Text,inputs[2].Text,inputs[3].Text);note.Text="Project information saved.";}catch(Exception ex){MessageBox.Show(this,ex.Message,"Project Information");}};AcceptButton=save;Action fit=()=>{int width=Math.Min(960,Math.Max(500,scroll.ClientSize.Width-64)),columns=width<720?1:2;body.Width=width;fields.Width=width;fields.SuspendLayout();try{foreach(Control group in fields.Controls)fields.SetColumnSpan(group,1);fields.ColumnCount=columns;fields.ColumnStyles.Clear();for(int c=0;c<columns;c++)fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/columns));var groups=inputs.Select(t=>t.Parent).ToArray();foreach(var field in groups)fields.Controls.Remove(field);for(int i=0;i<groups.Length;i++){groups[i].Width=(i==0?width:width/columns)-18;inputs[i].Width=groups[i].Width-12;fields.Controls.Add(groups[i],i==0?0:(i-1)%columns,i==0?0:1+(i-1)/columns);fields.SetColumnSpan(groups[i],i==0?columns:1);}}finally{fields.ResumeLayout(true);}note.MaximumSize=new Size(width,0);};Resize+=(s,e)=>fit();Shown+=(s,e)=>fit();fit();}
}
}
